#!/usr/bin/env python3
"""Independent no-write verification for P15D outputs and generated P15 milestone."""
from pathlib import Path
import json
import hashlib
import numpy as np
import pandas as pd

ROOT=Path.home()/"ltd-storage/results/diagnostics/P15D-HIST-PAIRED-V1"
FILES={"P15D_pairs.csv","P15D_day_bootstrap.csv","P15D_site_counts.csv",
       "P15D_day_counts.csv","P15_MILESTONE_AUTOGENERATED.md"}

def sha256(path):
    h=hashlib.sha256()
    with path.open("rb") as f:
        for part in iter(lambda:f.read(1048576),b""):h.update(part)
    return h.hexdigest()

def run():
    m=json.loads((ROOT/"P15D_manifest.json").read_text())
    if m.get("stage")!="P15D_HIST_PAIRED_M0_M1" or m.get("status")!="POSTHOC_DESCRIPTIVE":
        raise RuntimeError("MILESTONE_STAGE_NOT_MATCHED")
    for k in ("independent_confirmation","promotion_allowed","future_b_opened",
              "dataset_c_opened","training_allowed"):
        if m.get(k) is not False:raise RuntimeError("POLICY_FLAG_MISMATCH: "+k)
    if set(m.get("outputs_sha256",{}))!=FILES:
        raise RuntimeError("OUTPUT_MANIFEST_INCOMPLETE")
    for name,digest in m["outputs_sha256"].items():
        if sha256(ROOT/name)!=digest:raise RuntimeError("OUTPUT_SHA_INVALID: "+name)
    print("P15D_INDEPENDENT_SHA_VERIFIED 5/5")
    p=pd.read_csv(ROOT/"P15D_pairs.csv")
    ci=pd.read_csv(ROOT/"P15D_day_bootstrap.csv")
    st=pd.read_csv(ROOT/"P15D_site_counts.csv")
    dy=pd.read_csv(ROOT/"P15D_day_counts.csv")
    keys=["origin","window","comparison"]
    if len(p)!=len(ci)!=12:raise RuntimeError("EXPECTED_12_ROWS")
    if len(p)!=12 or len(ci)!=12:raise RuntimeError("EXPECTED_12_ROWS")
    if p.duplicated(keys).any() or ci.duplicated(keys).any():
        raise RuntimeError("DUPLICATE_PAIRS")
    if set(p.origin)!={"ORIGIN14","ORIGIN28"} or set(p.window)!={"NEAR","MID","FAR"}:
        raise RuntimeError("HISTORICAL_COHORT_MISMATCH")
    if set(p.comparison)!={"Macro M1-M0","Hybrid U3xM1-U3xM0"}:
        raise RuntimeError("PAIR_DEFINITIONS_CHANGED")
    if (ci.day_blocks<2).any():
        raise RuntimeError("TOO_FEW_DAYS")
    if len(p.merge(ci,on=keys,validate="one_to_one"))!=12:
        raise RuntimeError("BOOTSTRAP_MATCHING_FAILED")
    if not np.allclose(p.delta_accuracy,(p.rescued-p.harmed)/p.n,atol=1e-10):
        raise RuntimeError("PAIRED_ACCURACY_IDENTITY_FAILED")
    for key,g in p.groupby(keys):
        mask=lambda frame:(frame.origin==key[0])&(frame.window==key[1])&(frame.comparison==key[2])
        for f in (st,dy):
            x=f.loc[mask(f)]
            for col,expected in [("n",int(g.iloc[0].n)),("rescued",int(g.iloc[0].rescued)),("harmed",int(g.iloc[0].harmed))]:
                if int(x[col].sum())!=expected:
                    raise RuntimeError("SITES_OR_DAYS_NOT_RECONCILED: "+str((key,col)))
    assert "# LTD-Attack" in (ROOT/"P15_MILESTONE_AUTOGENERATED.md").read_text()
    print("P15D_12_PAIRS_COUNTS_BOOTSTRAP_RECONCILED")
    print("P15_SCIENTIFIC_MILESTONE_READY",ROOT/"P15_MILESTONE_AUTOGENERATED.md")
    f=p[p.window=="FAR"][["origin","comparison","delta_accuracy","delta_macro_f1","delta_top5_accuracy"]]
    print(f.to_string(index=False,float_format=lambda x:f"{x:+.6f}"))

if __name__=="__main__":run()
